SELECT p.*, c.category_name FROM product p LEFT JOIN category c ON p.category_id = c.category_id WHERE 1 = 1
AND p.product_name LIKE CONCAT('%', #{keyword}, '%')
AND p.category_id = #{categoryId}
ORDER BY p.product_id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM product p WHERE p.status = 1
AND p.product_name LIKE CONCAT('%', #{keyword}, '%')
AND p.category_id = #{categoryId}

